import type { Metadata } from "next";

export const metadata: Metadata = {
  title: "Agent response | vip/ui",
  description:
    "A local, scripted agent response with tool calls and linked sources.",
};

export default function AgentLayout({
  children,
}: LayoutProps<"/examples/agent">) {
  return children;
}

import { AgentWorkspace } from "./workspace";

export default function AgentPage() {
  return <AgentWorkspace />;
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";
import { CheckCircle, CloseCircle } from "reicon-react";
import { cn } from "./utils";

export type AgentStatusState = "thinking" | "working" | "complete" | "error";

export interface AgentStatusProps
  extends Omit<ComponentProps<"output">, "children"> {
  label: string;
  state: AgentStatusState;
  detail?: string;
}

const stateLabels: Record<AgentStatusState, string> = {
  thinking: "Thinking",
  working: "Using a tool",
  complete: "Complete",
  error: "Needs attention",
};

export function AgentStatus({
  label,
  state,
  detail,
  className,
  ...props
}: AgentStatusProps) {
  const reduceMotion = useReducedMotion() === true;
  const active = state === "thinking" || state === "working";

  return (
    <output
      {...props}
      data-slot="agent-status"
      data-state={state}
      aria-live="polite"
      aria-atomic="true"
      className={cn(
        "flex min-w-0 items-center gap-3 rounded-xl border border-border bg-card px-4 py-3 text-sm shadow-[var(--shadow-card)]",
        className,
      )}
    >
      <span
        aria-hidden="true"
        className={cn(
          "grid size-8 shrink-0 place-items-center rounded-lg bg-accent text-primary",
          state === "complete" && "bg-success-subtle text-success",
          state === "error" && "bg-destructive/10 text-destructive",
        )}
      >
        {active ? (
          <span className="flex items-center gap-0.5">
            {[0, 1, 2].map((index) => (
              <motion.span
                key={index}
                className="size-1 rounded-full bg-current"
                initial={false}
                animate={
                  reduceMotion
                    ? { opacity: 1, y: 0 }
                    : { opacity: [0.35, 1, 0.35], y: [0, -2, 0] }
                }
                transition={
                  reduceMotion
                    ? { duration: 0 }
                    : {
                        duration: 1.1,
                        delay: index * 0.13,
                        repeat: Infinity,
                        ease: "easeInOut",
                      }
                }
              />
            ))}
          </span>
        ) : state === "complete" ? (
          <CheckCircle size={17} />
        ) : (
          <CloseCircle size={17} />
        )}
      </span>
      <span className="min-w-0 flex-1">
        <span className="block font-medium text-foreground">{label}</span>
        {detail && (
          <span className="mt-0.5 block text-xs leading-5 text-muted-foreground">
            {detail}
          </span>
        )}
      </span>
      <span className="shrink-0 self-start text-xs text-muted-foreground">
        {stateLabels[state]}
      </span>
    </output>
  );
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost:
        "text-foreground hover:bg-muted data-[pressed]:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
      minimal:
        "text-muted-foreground hover:bg-muted hover:text-foreground data-[pressed]:bg-muted data-[pressed]:text-foreground",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 data-[pressed]:bg-destructive/90",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      layout={reduceMotion ? false : layout}
      whileHover={
        isStatic || reduceMotion || props.isDisabled
          ? undefined
          : { scale: 1.015 }
      }
      whileTap={
        isStatic || reduceMotion || props.isDisabled
          ? undefined
          : { scale: 0.96 }
      }
      transition={{ type: "spring", stiffness: 500, damping: 36 }}
      className={composeRenderProps(className, (className) =>
        buttonStyles({ variant, size, className }),
      )}
      {...props}
    />
  );
}

import type { ComponentProps, ElementType } from "react";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonLinkStyles,
} from "./button-styles";

type ButtonLinkProps = Omit<ComponentProps<"a">, "href"> & {
  href: string;
  as?: ElementType;
  variant?: ButtonVariant;
  size?: ButtonSize;
};

export function ButtonLink({
  children,
  className,
  as: Element = "a",
  variant = "default",
  size = "default",
  ...props
}: ButtonLinkProps) {
  return (
    <Element
      {...props}
      data-slot="button-link"
      data-variant={variant}
      data-size={size}
      className={buttonLinkStyles({ variant, size, className })}
    >
      {children}
    </Element>
  );
}

import type { ComponentProps, ReactNode } from "react";
import { cn } from "./utils";

export interface MessageProps extends ComponentProps<"article"> {
  sender: string;
  side?: "incoming" | "outgoing" | "system";
  avatar?: ReactNode;
  timestamp?: string;
  dateTime?: string;
  status?: string;
  actions?: ReactNode;
}

export function Message({
  sender,
  side = "incoming",
  avatar,
  timestamp,
  dateTime,
  status,
  actions,
  children,
  className,
  ...props
}: MessageProps) {
  return (
    <article
      {...props}
      data-slot="message"
      data-side={side}
      aria-label={props["aria-label"] ?? `${sender} message`}
      className={cn(
        "flex min-w-0 items-start gap-2.5",
        side === "outgoing" && "justify-end",
        side === "system" && "justify-center",
        className,
      )}
    >
      {side === "incoming" && avatar}
      <div
        className={cn(
          "min-w-0 max-w-[88%] sm:max-w-[75%]",
          side === "incoming" && avatar && "max-w-[calc(100%_-_3.25rem)]",
          side === "system" && "max-w-full text-center",
        )}
      >
        {side !== "system" && (
          <p
            data-slot="message-sender"
            className="mb-1 px-1 text-xs font-medium text-muted-foreground"
          >
            {sender}
          </p>
        )}
        <div
          data-slot="message-content"
          className={cn(
            "min-w-0 whitespace-pre-wrap [overflow-wrap:anywhere] rounded-2xl px-4 py-3 text-sm leading-6",
            side === "outgoing" &&
              "rounded-tr-md bg-accent text-accent-foreground",
            side === "incoming" &&
              "rounded-tl-md border border-border bg-card text-card-foreground shadow-[var(--shadow-card)]",
            side === "system" && "bg-muted/70 text-muted-foreground",
          )}
        >
          {children}
        </div>
        {(timestamp || status || actions) && (
          <div className="mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 px-1 text-xs text-muted-foreground">
            {timestamp && (
              <time dateTime={dateTime} data-slot="message-time">
                {timestamp}
              </time>
            )}
            {status && <span data-slot="message-status">{status}</span>}
            {actions && (
              <div data-slot="message-actions" className="flex gap-1">
                {actions}
              </div>
            )}
          </div>
        )}
      </div>
    </article>
  );
}

"use client";

import {
  AnimatePresence,
  type HTMLMotionProps,
  motion,
  useIsPresent,
  useReducedMotion,
} from "motion/react";
import type { ReactNode } from "react";
import { cn } from "./utils";

export interface PresenceProps
  extends Omit<
    HTMLMotionProps<"div">,
    "ref" | "children" | "initial" | "animate" | "exit" | "transition"
  > {
  show: boolean;
  children: ReactNode;
  as?: "div" | "span";
  distance?: number;
  duration?: number;
}

function PresenceContent({
  as,
  children,
  className,
  distance = 8,
  duration = 0.22,
  ...props
}: Omit<PresenceProps, "show">) {
  const isPresent = useIsPresent();
  const reducedMotion = useReducedMotion();
  const Element = as === "span" ? motion.span : motion.div;

  return (
    <Element
      {...props}
      data-slot="presence"
      className={cn(className)}
      inert={!isPresent}
      aria-hidden={!isPresent || undefined}
      initial={reducedMotion ? false : { opacity: 0, y: distance }}
      animate={{ opacity: 1, y: 0 }}
      exit={reducedMotion ? { opacity: 0 } : { opacity: 0, y: -distance }}
      transition={{
        duration: reducedMotion ? 0 : duration,
        ease: [0.22, 1, 0.36, 1],
      }}
    >
      {children}
    </Element>
  );
}

export function Presence({ show, ...props }: PresenceProps) {
  return (
    <AnimatePresence initial={false}>
      {show && <PresenceContent key="content" {...props} />}
    </AnimatePresence>
  );
}

"use client";

import { Link as AriaLink, type LinkProps } from "react-aria-components";
import { ArrowUpRight } from "reicon-react";
import { cn } from "./utils";

export interface SourceLinkProps
  extends Omit<LinkProps, "children" | "className"> {
  href: string;
  label: string;
  source: string;
  index?: number;
  description?: string;
  className?: string;
}

export function SourceLink({
  label,
  source,
  index,
  description,
  className,
  ...props
}: SourceLinkProps) {
  return (
    <AriaLink
      {...props}
      data-slot="source-link"
      className={cn(
        "group flex min-w-0 items-start gap-3 rounded-xl border border-border bg-card p-3.5 text-start shadow-[var(--shadow-card)] outline-none motion-safe:transition-[border-color,background-color,transform] motion-safe:duration-200 hover:border-primary/40 hover:bg-accent/30 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring motion-safe:hover:-translate-y-0.5 data-[disabled]:cursor-default data-[disabled]:opacity-50 motion-safe:data-[disabled]:hover:translate-y-0",
        className,
      )}
    >
      <span
        aria-hidden="true"
        className="grid size-8 shrink-0 place-items-center rounded-lg bg-accent font-mono text-xs font-semibold text-primary"
      >
        {index ?? <ArrowUpRight size={16} />}
      </span>
      <span className="min-w-0 flex-1">
        <span className="block text-sm font-medium leading-5 text-foreground [overflow-wrap:anywhere]">
          {label}
        </span>
        <span className="mt-0.5 block text-xs leading-5 text-muted-foreground [overflow-wrap:anywhere]">
          {source}
        </span>
        {description && (
          <span className="mt-1 block text-xs leading-5 text-muted-foreground [overflow-wrap:anywhere]">
            {description}
          </span>
        )}
      </span>
      <ArrowUpRight
        size={16}
        aria-hidden="true"
        className="mt-0.5 shrink-0 text-muted-foreground motion-safe:transition-transform motion-safe:duration-200 motion-safe:group-hover:-translate-y-0.5 motion-safe:group-hover:translate-x-0.5"
      />
    </AriaLink>
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { createContext, type ReactNode, useContext } from "react";
import { DisclosureStateContext } from "react-aria-components";
import { cn } from "./utils";

export const CollapsibleIdsContext = createContext<{
  triggerId: string;
  panelId: string;
} | null>(null);

type CollapsiblePanelProps = Omit<
  HTMLMotionProps<"div">,
  | "animate"
  | "initial"
  | "transition"
  | "id"
  | "aria-hidden"
  | "inert"
  | "children"
> & { children?: ReactNode };

export function CollapsiblePanel({
  children,
  className,
  role = "group",
  ...props
}: CollapsiblePanelProps) {
  const ids = useContext(CollapsibleIdsContext);
  const isExpanded = useContext(DisclosureStateContext)?.isExpanded;
  const reduceMotion = useReducedMotion();
  if (!ids) throw new Error("CollapsiblePanel must be inside a disclosure.");

  return (
    <motion.div
      data-slot="collapsible-panel"
      {...props}
      id={ids.panelId}
      role={role}
      aria-labelledby={ids.triggerId}
      aria-hidden={!isExpanded}
      inert={!isExpanded}
      className={cn("overflow-hidden", className)}
      initial={false}
      animate={{ height: isExpanded ? "auto" : 0, opacity: isExpanded ? 1 : 0 }}
      transition={{
        height: { duration: reduceMotion ? 0 : 0.22, ease: [0.23, 1, 0.32, 1] },
        opacity: { duration: reduceMotion ? 0 : 0.15, ease: "easeOut" },
      }}
    >
      {children}
    </motion.div>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { type ComponentProps, type ReactNode, useContext, useId } from "react";
import {
  Disclosure as AriaDisclosure,
  Button,
  type ButtonProps,
  composeRenderProps,
  type DisclosureProps,
  DisclosureStateContext,
  Heading,
} from "react-aria-components";
import { ChevronDown } from "reicon-react";
import { cn } from "./utils";
import { CollapsibleIdsContext, CollapsiblePanel } from "./collapsible-panel";

export function Disclosure({
  className,
  children,
  ...props
}: DisclosureProps & React.RefAttributes<HTMLDivElement>) {
  const id = useId();
  return (
    <CollapsibleIdsContext.Provider
      value={{ triggerId: `${id}-trigger`, panelId: `${id}-panel` }}
    >
      <AriaDisclosure
        {...props}
        data-slot="disclosure"
        className={composeRenderProps(className, (className) =>
          cn("rounded-lg border border-border bg-card", className),
        )}
      >
        {children}
      </AriaDisclosure>
    </CollapsibleIdsContext.Provider>
  );
}

export function DisclosureHeader({
  children,
  className,
  ...props
}: Omit<ButtonProps, "children"> & { children: ReactNode }) {
  const isExpanded = useContext(DisclosureStateContext)?.isExpanded;
  const ids = useContext(CollapsibleIdsContext);
  const reduceMotion = useReducedMotion();
  return (
    <Heading className="m-0 text-sm font-semibold">
      <Button
        {...props}
        data-slot="disclosure-header"
        slot="trigger"
        id={ids?.triggerId}
        aria-controls={ids?.panelId}
        className={composeRenderProps(className, (className) =>
          cn(
            "flex min-h-11 w-full cursor-pointer items-center justify-between gap-3 rounded-lg px-4 text-start data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring hover:bg-muted",
            className,
          ),
        )}
      >
        <span>{children}</span>
        <motion.span
          className="shrink-0 text-muted-foreground"
          aria-hidden="true"
          initial={false}
          animate={{ rotate: isExpanded ? 180 : 0 }}
          transition={{
            type: "tween",
            duration: reduceMotion ? 0 : 0.2,
            ease: [0.23, 1, 0.32, 1],
          }}
        >
          <ChevronDown size={16} />
        </motion.span>
      </Button>
    </Heading>
  );
}

export function DisclosurePanel({
  className,
  children,
  ...props
}: ComponentProps<typeof CollapsiblePanel>) {
  return (
    <CollapsiblePanel
      {...props}
      data-slot="disclosure-panel"
      className={cn("text-sm leading-6 text-muted-foreground", className)}
    >
      <div className="px-4 pb-4">{children}</div>
    </CollapsiblePanel>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps, ReactNode } from "react";
import { CheckCircle, CloseCircle } from "reicon-react";
import { cn } from "./utils";
import { Disclosure, DisclosureHeader, DisclosurePanel } from "./disclosure";

export type ToolCallStatus = "running" | "complete" | "error";

export function ToolCall({
  className,
  ...props
}: Omit<ComponentProps<typeof Disclosure>, "className"> & {
  className?: string;
}) {
  return (
    <Disclosure
      {...props}
      data-slot="tool-call"
      className={cn("min-w-0 overflow-hidden rounded-xl", className)}
    />
  );
}

export interface ToolCallTriggerProps
  extends Omit<
    ComponentProps<typeof DisclosureHeader>,
    "children" | "className"
  > {
  name: string;
  status: ToolCallStatus;
  summary?: string;
  className?: string;
}

export function ToolCallTrigger({
  name,
  status,
  summary,
  className,
  ...props
}: ToolCallTriggerProps) {
  const reduceMotion = useReducedMotion() === true;
  return (
    <DisclosureHeader
      {...props}
      data-slot="tool-call-trigger"
      className={cn(
        "min-h-14 rounded-xl px-4 py-3 hover:bg-muted/70 [&>span:first-child]:min-w-0 [&>span:first-child]:flex-1",
        className,
      )}
    >
      <span className="flex min-w-0 items-center gap-3">
        <span
          aria-hidden="true"
          className={cn(
            "grid size-8 shrink-0 place-items-center rounded-lg bg-accent text-primary",
            status === "complete" && "bg-success-subtle text-success",
            status === "error" && "bg-destructive/10 text-destructive",
          )}
        >
          {status === "running" ? (
            <motion.span
              className="size-2 rounded-full bg-current"
              initial={false}
              animate={
                reduceMotion ? { opacity: 1 } : { opacity: [0.4, 1, 0.4] }
              }
              transition={
                reduceMotion
                  ? { duration: 0 }
                  : { duration: 1.2, repeat: Infinity }
              }
            />
          ) : status === "complete" ? (
            <CheckCircle size={17} />
          ) : (
            <CloseCircle size={17} />
          )}
        </span>
        <span className="min-w-0 text-start">
          <span className="block font-mono text-xs font-semibold text-foreground [overflow-wrap:anywhere]">
            {name}
          </span>
          {summary && (
            <span className="mt-0.5 block text-xs font-normal leading-5 text-muted-foreground">
              {summary}
            </span>
          )}
        </span>
        <span
          aria-live="polite"
          className="ms-auto shrink-0 text-xs font-normal text-muted-foreground"
        >
          {status === "running"
            ? "Running"
            : status === "complete"
              ? "Done"
              : "Failed"}
        </span>
      </span>
    </DisclosureHeader>
  );
}

export function ToolCallPanel({
  children,
  className,
  ...props
}: Omit<ComponentProps<typeof DisclosurePanel>, "children"> & {
  children?: ReactNode;
}) {
  return (
    <DisclosurePanel
      {...props}
      data-slot="tool-call-panel"
      className={cn("border-t border-border/70", className)}
    >
      <div className="min-w-0 pt-3 text-sm leading-6 text-foreground [overflow-wrap:anywhere]">
        {children}
      </div>
    </DisclosurePanel>
  );
}
